/// Size of the snmpTrapAddress.0 varbind: 30 11 06 09 <9-byte OID> 40 04 <address>
static const size_t TRAP_ADDRESS_VARBIND_LEN = 19;

static const uint8_t NO_IPV4[4] = {0, 0, 0, 0};

static SnmpDeviceState mainsState(bool present, uint32_t changes, uint32_t lastChange) {
    SnmpDeviceState s;
    memset(&s, 0, sizeof(s));
    s.uptimeTicks = lastChange + 500;
    s.mainsPresent = present;
    s.mainsChanges = changes;
    s.mainsLastChangeTicks = lastChange;
    return s;
}

static void test_mains_lost_trap_matches_netsnmp_byte_for_byte() {
    uint8_t buf[256];
    size_t len = snmpBuildMainsTrap("public", AGENT, mainsState(false, 1, 12345), buf, sizeof(buf));
    TEST_ASSERT_EQUAL_size_t(sizeof(NETSNMP_MAINS_LOST), len);
    TEST_ASSERT_EQUAL_HEX8_ARRAY(NETSNMP_MAINS_LOST, buf, sizeof(NETSNMP_MAINS_LOST));
}

static void test_cold_start_trap_matches_netsnmp_byte_for_byte() {
    uint8_t buf[128];
    size_t len = snmpBuildColdStartTrap("public", AGENT, 42, buf, sizeof(buf));
    TEST_ASSERT_EQUAL_size_t(sizeof(NETSNMP_COLD_START), len);
    TEST_ASSERT_EQUAL_HEX8_ARRAY(NETSNMP_COLD_START, buf, sizeof(NETSNMP_COLD_START));
}

static void test_auth_failure_trap_differs_from_cold_start_only_in_generic_type() {
    uint8_t buf[128];
    size_t len = snmpBuildAuthFailureTrap("public", AGENT, 42, buf, sizeof(buf));
    TEST_ASSERT_EQUAL_size_t(sizeof(NETSNMP_COLD_START), len);
    uint8_t expected[sizeof(NETSNMP_COLD_START)];
    memcpy(expected, NETSNMP_COLD_START, sizeof(expected));
    expected[33] = 4;  // generic-trap: authenticationFailure
    TEST_ASSERT_EQUAL_HEX8_ARRAY(expected, buf, sizeof(expected));
}

/// Decode the PDU fields of a trap
struct DecodedTrap {
    Oid enterprise;
    const uint8_t* addr;
    int32_t generic, specific;
    uint32_t timestamp;
    uint8_t count;
    Oid names[SNMP_TRAP_MAX_VARBINDS];
    uint8_t tags[SNMP_TRAP_MAX_VARBINDS];
    int32_t ints[SNMP_TRAP_MAX_VARBINDS];
    uint32_t uints[SNMP_TRAP_MAX_VARBINDS];
};

static DecodedTrap decode(const uint8_t* buf, size_t len) {
    DecodedTrap d;
    memset(&d, 0, sizeof(d));
    BerReader top(buf, len), msg, pdu, list, vb;
    int32_t version;
    const uint8_t* s;
    size_t slen;
    TEST_ASSERT_TRUE(top.readSequence(BerTag::Sequence, msg));
    TEST_ASSERT_TRUE(msg.readInteger(version));
    TEST_ASSERT_TRUE(msg.readOctetString(s, slen));
    TEST_ASSERT_TRUE(msg.readSequence(BerTag::Trap, pdu));
    TEST_ASSERT_TRUE(pdu.readOid(d.enterprise));
    TEST_ASSERT_TRUE(pdu.readOctetString(d.addr, slen, BerTag::IpAddress));
    TEST_ASSERT_EQUAL_size_t(4, slen);
    TEST_ASSERT_TRUE(pdu.readInteger(d.generic));
    TEST_ASSERT_TRUE(pdu.readInteger(d.specific));
    TEST_ASSERT_TRUE(pdu.readUnsigned(BerTag::TimeTicks, d.timestamp));
    TEST_ASSERT_TRUE(pdu.readSequence(BerTag::Sequence, list));
    TEST_ASSERT_TRUE(pdu.atEnd());
    while (list.remaining() > 0) {
        uint8_t i = d.count++;
        TEST_ASSERT_TRUE(list.readSequence(BerTag::Sequence, vb));
        TEST_ASSERT_TRUE(vb.readOid(d.names[i]));
        TEST_ASSERT_TRUE(vb.peekTag(d.tags[i]));
        if (d.tags[i] == BerTag::Integer) {
            TEST_ASSERT_TRUE(vb.readInteger(d.ints[i]));
        } else {
            TEST_ASSERT_TRUE(vb.readUnsigned(d.tags[i], d.uints[i]));
        }
    }
    TEST_ASSERT_TRUE(list.atEnd());
    return d;
}

static void test_mains_restored_trap_fields() {
    uint8_t buf[256];
    size_t len = snmpBuildMainsTrap("public", AGENT, mainsState(true, 2, 99000), buf, sizeof(buf));
    DecodedTrap d = decode(buf, len);
    TEST_ASSERT_EQUAL_INT32(6, d.generic);
    TEST_ASSERT_EQUAL_INT32((int32_t)MainsTrap::PowerRestored, d.specific);
    TEST_ASSERT_EQUAL_UINT32(99000, d.timestamp);
    TEST_ASSERT_EQUAL_HEX8_ARRAY(AGENT, d.addr, 4);
    TEST_ASSERT_EQUAL_UINT8(3, d.count);
    TEST_ASSERT_EQUAL_INT32(1, d.ints[0]);
    TEST_ASSERT_EQUAL_UINT32(2, d.uints[1]);
    TEST_ASSERT_EQUAL_UINT32(99000, d.uints[2]);
}

static void test_trap_varbinds_are_the_mib_objects() {
    uint8_t buf[256];
    DecodedTrap d = decode(buf, snmpBuildMainsTrap("public", AGENT, mainsState(false, 5, 7), buf, sizeof(buf)));
    for (uint8_t i = 0; i < 3; i++) {
        Oid expected = {{1, 3, 6, 1, 4, 1, 63050, (uint32_t)i + 1, 0}, 9};
        TEST_ASSERT_EQUAL(0, oidCompare(expected, d.names[i]));
        static MibObject found;
        TEST_ASSERT_TRUE(mibGet(d.names[i], mainsState(false, 5, 7), found));
    }
    TEST_ASSERT_EQUAL_HEX8(BerTag::Integer, d.tags[0]);
    TEST_ASSERT_EQUAL_HEX8(BerTag::Counter32, d.tags[1]);
    TEST_ASSERT_EQUAL_HEX8(BerTag::TimeTicks, d.tags[2]);
}

